applySettings();renderArmory();for(const clue of intel)clue.mesh.visible=false;$(".team.aegis small").textContent="AEGIS";$(".team.nova small").textContent="NOVA";$("#playerRole").textContent="5V5";$("#start").innerHTML='<div class="lobby-shell"><aside class="lobby-nav"><p>REDACTED</p><h1>FPS</h1><button class="active" data-lobby-tab="play">게임</button><button data-lobby-tab="loadout">무기고</button><button data-lobby-tab="settings">설정</button></aside><main class="lobby-main"><section class="lobby-panel active" data-panel="play"><small>GAME MODE</small><h2>전투 준비</h2><div class="mode-grid"><button class="mode-card active" data-mode="duel"><b>5V5</b><strong>일반전</strong><span>7라운드 선승 · 링크 코어 작전</span></button><button class="mode-card" data-mode="quick"><b>FT3</b><strong>빠른전</strong><span>3라운드 선승 · 짧은 경기</span></button><button class="mode-card" data-mode="training"><b>∞</b><strong>훈련장</strong><span>시간·승패 없이 사격 연습</span></button></div><div class="lobby-summary"><span>맵 <b>CASTER</b></span><span>인원 <b id="lobbyPlayers">5 VS 5</b></span><span>서버 <b>AUTHORITY</b></span></div><button id="deploy" class="lobby-deploy">게임 시작</button></section><section class="lobby-panel" data-panel="loadout"><small>LOADOUT</small><h2>무기고</h2><p>게임 안에서 B를 눌러 구매하거나, 아래 버튼으로 무기 성능을 확인합니다.</p><button id="lobbyArmory" class="lobby-action">무기 성능 보기</button></section><section class="lobby-panel" data-panel="settings"><small>SETTINGS</small><h2>게임 설정</h2><div class="lobby-settings"><label>마우스 감도 <b id="lobbySensitivityValue">1.00</b><input id="lobbySensitivity" type="range" min="0.4" max="2.5" step="0.05"></label><label>시야각 <b id="lobbyFovValue">72</b><input id="lobbyFov" type="range" min="60" max="95" step="1"></label><label>조준점 색상<input id="lobbyCrosshairColor" type="color"></label><label class="lobby-toggle">그림자<input id="lobbyShadows" type="checkbox"></label></div></section></main></div>';
