const operatorSelect=document.createElement("section");operatorSelect.className="operator-select";operatorSelect.innerHTML='<small>CONTRACT OPERATOR</small><div>'+Object.entries(operatorProfiles).map(([key,profile])=>`<button data-operator="${key}" class="${key===selectedOperator?"active":""}"><b>${profile.name}</b><span>${profile.role}</span><em>${profile.description}</em></button>`).join("")+'</div>';const playPanel=document.querySelector('[data-panel="play"]');playPanel.insertBefore(operatorSelect,playPanel.querySelector(".lobby-summary"));for(const button of operatorSelect.querySelectorAll("[data-operator]"))button.onclick=()=>{selectedOperator=button.dataset.operator;operatorSelect.querySelectorAll("button").forEach(item=>item.classList.toggle("active",item===button));notice(`${operatorProfiles[selectedOperator].name} CONTRACT ACCEPTED`)};
