const lobbySensitivity=$("#lobbySensitivity"),lobbyFov=$("#lobbyFov"),lobbyColor=$("#lobbyCrosshairColor"),lobbyShadows=$("#lobbyShadows");lobbySensitivity.value=settings.sensitivity;lobbyFov.value=settings.fov;lobbyColor.value=settings.crosshairColor;lobbyShadows.checked=!!settings.shadows;function saveLobbySettings(){settings.sensitivity=+lobbySensitivity.value;settings.fov=+lobbyFov.value;settings.crosshairColor=lobbyColor.value;settings.shadows=lobbyShadows.checked;$("#lobbySensitivityValue").textContent=settings.sensitivity.toFixed(2);$("#lobbyFovValue").textContent=settings.fov;saveSettings()}for(const input of [lobbySensitivity,lobbyFov,lobbyColor,lobbyShadows])input.oninput=saveLobbySettings;saveLobbySettings();


function setTouchPlaying(active){document.body.classList.toggle("touch-playing",touchDevice&&active)}function requestPlay(){ensureAudio();if(touchDevice){locked=true;setTouchPlaying(true);$("#start").classList.add("hidden");$("#armory").classList.add("hidden");$("#pause").classList.add("hidden");return}renderer.domElement.requestPointerLock()}$("#deploy").onclick=()=>{started=true;round.number=1;round.aegis=round.nova=0;for(const clue of intel)clue.mesh.visible=gameMode==="training";if(gameMode==="training"){round.phase="active";round.phaseEnds=Infinity;resetRoundPositions();setupTrainingBots();showStory("훈련 기록 복원","거리별 전투 더미와 CASTER 내부의 네 현장 기록을 확인하라.","SOLO TRAINING · INTELLIGENCE");notice("TRAINING · 5 TARGETS")}else beginRound(performance.now());const room=new URLSearchParams(location.search).get("room");authority.connect(room).then(()=>notice(room?"SERVER JOINED":"AUTHORITY ONLINE")).catch(()=>notice("LOCAL MODE"));requestPlay()};$("#resume").onclick=requestPlay;
document.addEventListener("pointerlockchange",()=>{locked=document.pointerLockElement===renderer.domElement;if(!locked){resetAim();firing=false}if(isPreview)return;$("#start").classList.toggle("hidden",started);$("#armory").classList.toggle("hidden",locked||!shopOpen);$("#pause").classList.toggle("hidden",locked||!started||shopOpen)});

document.addEventListener("mousemove",e=>{if(!locked||!playerAlive)return;yaw-=e.movementX*.0022*settings.sensitivity;pitch=clamp(pitch-e.movementY*.0018*settings.sensitivity,-1.35,1.35)});document.addEventListener("keydown",e=>{keys[e.code]=true;if(playerAlive&&!e.repeat&&e.code==="KeyQ")useAbility("scan",performance.now());if(playerAlive&&!e.repeat&&e.code==="KeyZ")useAbility("smoke",performance.now());if(playerAlive&&!e.repeat&&e.code==="KeyX")useAbility("stim",performance.now());if(!playerAlive&&!e.repeat&&(e.code==="KeyQ"||e.code==="ArrowLeft"))selectSpectator(-1);if(!playerAlive&&!e.repeat&&(e.code==="KeyE"||e.code==="ArrowRight"))selectSpectator(1);if(e.code==="Space"&&locked&&playerAlive&&grounded&&crouchAmount<.55){verticalVelocity=7;grounded=false}if(e.code==="KeyF"&&!e.repeat&&locked&&playerAlive)collectIntel();if(e.code==="KeyR"&&playerAlive)reload();if(e.code==="Digit1"&&playerAlive)selectSlot(1);if(e.code==="Digit2"&&playerAlive)selectSlot(2);if(e.code==="Digit3"&&playerAlive)selectSlot(3);if(e.code==="KeyB"&&!e.repeat&&playerAlive){shopOpen=!shopOpen;if(shopOpen){renderArmory();if(locked)document.exitPointerLock();else $("#armory").classList.remove("hidden")}else requestPlay()}});document.addEventListener("keyup",e=>keys[e.code]=false);document.addEventListener("mousedown",e=>{if(!locked||!playerAlive)return;if(e.button===0){firing=true;fire(performance.now())}if(e.button===2)keys.Mouse2=true});document.addEventListener("mouseup",e=>{if(e.button===0)firing=false;if(e.button===2)keys.Mouse2=false});document.addEventListener("contextmenu",e=>e.preventDefault());addEventListener("resize",()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});
document.addEventListener("auxclick",event=>{if(event.button===1){event.preventDefault();issueTeamPing(performance.now())}});
function installTouchControls(){if(!touchDevice)return;const controls=document.createElement("section");controls.className="mobile-fps-controls";controls.setAttribute("aria-label","모바일 FPS 조작");controls.innerHTML='<div class="mobile-look-pad" aria-label="화면 드래그 조준"></div><div class="mobile-move-pad" aria-label="이동 조이스틱"><i class="mobile-move-stick"></i></div><div class="mobile-action-grid"><button class="mobile-ability" data-ability-touch="scan">Q</button><button class="mobile-ability" data-ability-touch="smoke">Z</button><button class="mobile-ability" data-ability-touch="stim">X</button><button data-touch="shop">BUY</button><button data-touch="weapon">GUN</button><button data-touch="reload">R</button><button class="mobile-use" data-touch="use">USE</button><button data-touch="jump">JUMP</button><button class="mobile-ads" data-touch="ads">ADS</button><button class="mobile-fire" data-touch="fire">FIRE</button></div>';document.body.append(controls);const move=controls.querySelector(".mobile-move-pad"),stick=controls.querySelector(".mobile-move-stick"),look=controls.querySelector(".mobile-look-pad");let moveId=null,lookId=null,lastLook=null;const clearMove=()=>{moveId=null;keys.KeyW=keys.KeyA=keys.KeyS=keys.KeyD=false;stick.style.transform=""};const updateMove=event=>{const rect=move.getBoundingClientRect(),cx=rect.left+rect.width/2,cy=rect.top+rect.height/2,dx=event.clientX-cx,dy=event.clientY-cy,length=Math.hypot(dx,dy)||1,limit=42,nx=dx/Math.max(length,limit),ny=dy/Math.max(length,limit);stick.style.transform=`translate(${nx*limit}px,${ny*limit}px)`;keys.KeyW=ny<-.25;keys.KeyS=ny>.25;keys.KeyA=nx<-.25;keys.KeyD=nx>.25};move.addEventListener("pointerdown",event=>{event.preventDefault();moveId=event.pointerId;move.setPointerCapture(event.pointerId);updateMove(event)});move.addEventListener("pointermove",event=>{if(event.pointerId===moveId)updateMove(event)});move.addEventListener("pointerup",clearMove);move.addEventListener("pointercancel",clearMove);look.addEventListener("pointerdown",event=>{event.preventDefault();lookId=event.pointerId;lastLook={x:event.clientX,y:event.clientY};look.setPointerCapture(event.pointerId)});look.addEventListener("pointermove",event=>{if(event.pointerId!==lookId||!lastLook||!locked)return;const dx=event.clientX-lastLook.x,dy=event.clientY-lastLook.y;lastLook={x:event.clientX,y:event.clientY};yaw-=dx*.006*settings.sensitivity;pitch=clamp(pitch-dy*.005*settings.sensitivity,-1.35,1.35)});const clearLook=()=>{lookId=null;lastLook=null};look.addEventListener("pointerup",clearLook);look.addEventListener("pointercancel",clearLook);const hold=(name,on,off)=>{const button=controls.querySelector(`[data-touch="${name}"]`);button.addEventListener("pointerdown",event=>{event.preventDefault();event.stopPropagation();button.setPointerCapture(event.pointerId);button.classList.add("active");on()});const release=()=>{button.classList.remove("active");off?.()};button.addEventListener("pointerup",release);button.addEventListener("pointercancel",release)};hold("fire",()=>{if(!locked||!playerAlive)return;firing=true;fire(performance.now())},()=>firing=false);hold("ads",()=>keys.Mouse2=true,()=>keys.Mouse2=false);hold("use",()=>{keys.KeyE=true;collectIntel()},()=>keys.KeyE=false);controls.querySelector('[data-touch="jump"]').onclick=()=>{if(locked&&playerAlive&&grounded&&crouchAmount<.55){verticalVelocity=7;grounded=false}};controls.querySelector('[data-touch="reload"]').onclick=reload;controls.querySelector('[data-touch="weapon"]').onclick=()=>{const slots=[1,2,3],start=Math.max(0,slots.indexOf(equippedSlot));for(let offset=1;offset<=slots.length;offset++){const slot=slots[(start+offset)%slots.length];if(ownedSlots[slot]!=null){selectSlot(slot);break}}};controls.querySelector('[data-touch="shop"]').onclick=()=>{if(!playerAlive)return;locked=false;setTouchPlaying(false);shopOpen=true;renderArmory();$("#armory").classList.remove("hidden")};for(const button of controls.querySelectorAll("[data-ability-touch]"))button.onclick=()=>useAbility(button.dataset.abilityTouch,performance.now())}
installTouchControls();
function goLobby(){if(document.pointerLockElement)document.exitPointerLock();locked=false;setTouchPlaying(false);started=false;round.phase="idle";shopOpen=false;showBuyBarriers(false);resetLinkCore();resetSideEconomy();resetRoundPurchases();$("#matchEnd").classList.add("hidden");$("#roundReport").classList.add("hidden");$("#scoreboard").classList.add("hidden");$("#pause").classList.add("hidden");$("#start").classList.remove("hidden");for(const clue of intel)clue.mesh.visible=false;renderMatchHistory();renderDossier();renderArmory();renderRound()}$("#returnLobby").addEventListener("click",goLobby);$("#pauseLobby").addEventListener("click",goLobby);
